cd /tmp && for i in $(seq 32 126); do
  [ $i -eq 35 ] || [ $i -eq 37 ] || [ $i -eq 47 ] || [ $i -eq 63 ] || {
  c=$(printf "\\$(printf %03o $i)")
  o=$(/workspace/dataset/test12_executable --a "http://ex.com/a${c}b%41" --b B --c C --d D 2>/dev/null | sed -n 4p)
  seg=${o#http://ex.com/}; seg=${seg%%#*}
  case "$seg" in *2541*) v=INVALID;; *) v=valid;; esac
  printf '%02X %s  %-16s %s\n' $i "$c" "$seg" "$v"; }
done

cat > /tmp/model_urlpath.js <<'EOF'
// model: given raw path string (already TAB/LF/CR stripped, delimited), produce output path
const SAFE = new Set([..."ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!$&'()*+,-.:;=@_~"]);
function isWordNonAscii(cp){ // Python \w for non-ASCII: isalnum() (letter or numeric) or '_'
  const s = String.fromCodePoint(cp);
  return /[\p{L}\p{Nd}\p{Nl}\p{No}\p{Mn}\p{Mc}]/u.test(s);
}
function validEncoded(seg){
  let i=0;
  while(i<seg.length){
    const ch=seg[i];
    if(ch==='%'){ if(/^[0-9a-fA-F]{2}$/.test(seg.substr(i+1,2))){i+=3;continue;} return false; }
    const cp=seg.codePointAt(i); const w=String.fromCodePoint(cp).length;
    if(cp<128){ if(!SAFE.has(ch)) return false; i+=1; }
    else { if(!isWordNonAscii(cp)) return false; i+=w; }
  }
  return true;
}
function pctDecodeToText(seg){ // unquote with utf-8/replace, python split('%') semantics
  const bytes=[]; let i=0;
  while(i<seg.length){
    if(seg[i]==='%' && /^[0-9a-fA-F]{2}$/.test(seg.substr(i+1,2))){ bytes.push(parseInt(seg.substr(i+1,2),16)); i+=3; }
    else { const cp=seg.codePointAt(i); const s=String.fromCodePoint(cp); for(const b of Buffer.from(s,'utf8')) bytes.push(b); i+=s.length; }
  }
  return new TextDecoder('utf-8').decode(Buffer.from(bytes)); // WHATWG replace
}
function quote(text){
  let o='';
  for(const b of Buffer.from(text,'utf8')){
    const ch=String.fromCharCode(b);
    if(b<128 && SAFE.has(ch)) o+=ch; else o+='%'+b.toString(16).toUpperCase().padStart(2,'0');
  }
  return o;
}
function encPath(raw){
  return raw.split('/').map(s=> validEncoded(s)? quote(pctDecodeToText(s)) : quote(s)).join('/');
}
const arg=process.argv[2];
process.stdout.write(encPath(arg)+"\n");
EOF
node /tmp/model_urlpath.js 'a%%41' ; node /tmp/model_urlpath.js '%C3%A9%41'; node /tmp/model_urlpath.js 'a b%41'
